851	func (r *renderer) addBoolArg(value bool) string {
852		var v any
853		switch r.dialect {
854		case DialectSQLite:
855			if value {
856				v = 1
857			} else {
858				v = 0
859			}
860		default:
861			v = value
862		}
863		return r.addArg(v)
864	}
