866	func expectLiteral(expr ValueExpr) (any, error) {
867		lit, ok := expr.(*LiteralValue)
868		if !ok {
869			return nil, errors.New("expression must be a literal")
870		}
871		return lit.Value, nil
872	}
873	
874	func expectBool(expr ValueExpr) (bool, error) {
875		lit, err := expectLiteral(expr)
876		if err != nil {
877			return false, err
878		}
879		value, ok := lit.(bool)
880		if !ok {
881			return false, errors.New("boolean literal required")
882		}
883		return value, nil
884	}
885	
886	func expectNumericLiteral(expr ValueExpr) (int64, error) {
887		lit, err := expectLiteral(expr)
888		if err != nil {
889			return 0, err
890		}
891		return toInt64(lit)
892	}
893	
894	func toInt64(value any) (int64, error) {
895		switch v := value.(type) {
896		case int:
897			return int64(v), nil
898		case int32:
899			return int64(v), nil
900		case int64:
901			return v, nil
902		case uint32:
903			return int64(v), nil
904		case uint64:
905			return int64(v), nil
906		case float32:
907			return int64(v), nil
908		case float64:
909			return int64(v), nil
910		default:
911			return 0, errors.Errorf("cannot convert %T to int64", value)
912		}
913	}
914	
915	func sqlOperator(op ComparisonOperator) string {
916		return string(op)
917	}
918	
919	func qualifyColumn(d DialectName, col Column) string {
920		switch d {
921		case DialectPostgres:
922			return fmt.Sprintf("%s.%s", col.Table, col.Name)
923		default:
924			return fmt.Sprintf("`%s`.`%s`", col.Table, col.Name)
925		}
926	}
927	
928	func jsonPath(field Field) string {
929		return "$." + strings.Join(field.JSONPath, ".")
930	}
931	
932	func jsonExtractExpr(d DialectName, field Field) string {
933		column := qualifyColumn(d, field.Column)
934		switch d {
935		case DialectSQLite, DialectMySQL:
936			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
937		case DialectPostgres:
938			return buildPostgresJSONAccessor(column, field.JSONPath, true)
939		default:
940			return ""
941		}
942	}
943	
944	func jsonArrayExpr(d DialectName, field Field) string {
945		column := qualifyColumn(d, field.Column)
946		switch d {
947		case DialectSQLite, DialectMySQL:
948			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
949		case DialectPostgres:
950			return buildPostgresJSONAccessor(column, field.JSONPath, false)
951		default:
952			return ""
953		}
954	}
955	
956	func jsonArrayLengthExpr(d DialectName, field Field) string {
957		arrayExpr := jsonArrayExpr(d, field)
958		switch d {
959		case DialectSQLite:
960			return fmt.Sprintf("JSON_ARRAY_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
961		case DialectMySQL:
962			return fmt.Sprintf("JSON_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
963		case DialectPostgres:
964			return fmt.Sprintf("jsonb_array_length(COALESCE(%s, '[]'::jsonb))", arrayExpr)
965		default:
966			return ""
967		}
968	}
969	
970	func buildPostgresJSONAccessor(base string, path []string, terminalText bool) string {
971		expr := base
972		for idx, part := range path {
973			if idx == len(path)-1 && terminalText {
974				expr = fmt.Sprintf("%s->>'%s'", expr, part)
975			} else {
976				expr = fmt.Sprintf("%s->'%s'", expr, part)
977			}
978		}
979		return expr
980	}
981

